# Stan side of the "best variational approximation" search: many random restarts of mean-field
# ADVI on the Table S1 model, run with cmdstanr. The Stan program and data are generated by brms
# from the same formula, family and data as run_repro.R, so the model is exactly the brms model.
# Each restart is saved as a diagonal Normal over the unconstrained coordinates, in the order
# best_vi.py expects. `python best_vi.py score` then ranks all Stan and PyMC restarts by NumPyro ELBO.
#
# Usage:  Rscript best_vi_stan.R          # 50 restarts (seeds 1..50)
#         Rscript best_vi_stan.R 10       # a quick test with 10 (seeds 1..10)
#         Rscript best_vi_stan.R 11 15    # seeds 11..15 only, for parallel jobs; writes its own
#                                         #   part file best_vi/stan_restarts_moments_part_011-015.csv
# Resumable: seeds already in best_vi/stan_restarts_moments*.csv are skipped.
# Needs: tidyverse, brms, cmdstanr + CmdStan (see the install steps for cmdstanr).
# Writes: best_vi/stan_restarts_moments.csv (or a part file), best_vi/genus_levels.csv

suppressPackageStartupMessages({ library(tidyverse); library(brms); library(cmdstanr) })
args <- commandArgs(trailingOnly = TRUE)
dir.create("best_vi", showWarnings = FALSE)
if (length(args) >= 2) {
  seeds <- seq(as.integer(args[1]), as.integer(args[2]))
  out_file <- sprintf("best_vi/stan_restarts_moments_part_%03d-%03d.csv", min(seeds), max(seeds))
} else {
  seeds <- seq_len(if (length(args) == 1) as.integer(args[1]) else 50L)
  out_file <- "best_vi/stan_restarts_moments.csv"
}

# ADVI settings for every restart (same as the "adjusted" run in run_repro_vi.R)
vi_args <- list(algorithm = "meanfield", iter = 40000, grad_samples = 100,
                tol_rel_obj = 1e-5, output_samples = 10000, refresh = 0)

## ---- model: the same brms model as run_repro.R, but compiled by cmdstanr ----
dat <- read_csv("species.ecoregion.data.csv", show_col_types = FALSE) %>%
  mutate(MAT = base::scale(MAT), MAP = base::scale(MAP), Genus.factor = as_factor(Genus))
dat$Y <- cbind(TeB = dat$TeB, PrB = dat$PrB, DeB = dat$DeB)
dat$weightsInv <- 1 / dat$RMSE
form <- bf(Y | weights(weightsInv) ~ MAT + poly(MAP, 2) + (1 | Genus.factor), family = brms::dirichlet)

G <- nlevels(dat$Genus.factor)
write_csv(tibble(level = levels(dat$Genus.factor)), "best_vi/genus_levels.csv")  # python checks the order

stan_code <- make_stancode(form, data = dat, backend = "cmdstanr")
stan_data <- unclass(make_standata(form, data = dat))

# --- checks that the parameter mapping below is valid ---
# (1) brms must not shift the predictors (it centres columns inside Stan): ours are already centred.
Xs <- stan_data$X_muPrB
if (is.matrix(Xs)) {
  nonconst <- apply(Xs, 2, function(x) length(unique(x)) > 1)
  if (max(abs(colMeans(Xs[, nonconst, drop = FALSE]))) > 1e-8)
    stop("Predictors are not centred, so brms' Intercept differs from the PyMC intercept; mapping invalid.")
}
# (2) brms gives each response its own group-level block: sd_1 / z_1 for muPrB and sd_2 / z_2 for
#     muDeB (one random intercept each). Check that in the generated Stan code.
for (pattern in c("r_1_muPrB_1 = (sd_1[1] * (z_1[1]));", "r_2_muDeB_1 = (sd_2[1] * (z_2[1]));")) {
  if (!grepl(pattern, stan_code, fixed = TRUE))
    stop("Expected `", pattern, "` in the brms Stan code; the group-level mapping in this script must be changed.")
}

mod <- cmdstan_model(write_stan_file(stan_code))

## ---- canonical coordinate order (must match best_vi.py) ----
# b_Intercept(2) | b (3 x 2, row-major) | log sd (2) | z (G x 2, row-major) | log phi (1)
canon <- tibble(
  name = c(c("Intercept_muPrB", "Intercept_muDeB"),
           as.vector(rbind(sprintf("b_muPrB[%d]", 1:3), sprintf("b_muDeB[%d]", 1:3))),
           c("sd_1[1]", "sd_2[1]"),                                                # muPrB, muDeB
           unlist(lapply(seq_len(G), function(n) c(sprintf("z_1[1,%d]", n), sprintf("z_2[1,%d]", n)))),
           "phi"),
  is_log = c(rep(FALSE, 2 + 6), rep(TRUE, 2), rep(FALSE, 2 * G), TRUE))

read_vb_csv <- function(path) {
  lines <- readLines(path)
  df <- read.csv(text = lines[!startsWith(lines, "#")], check.names = FALSE)
  # CmdStan's CSV writes indexed names as b_muPrB.1 / z_1.1.3; rename them to the Stan-code
  # form b_muPrB[1] / z_1[1,3] used in `canon`
  names(df) <- vapply(names(df), function(n) {
    parts <- strsplit(n, ".", fixed = TRUE)[[1]]
    if (length(parts) == 1) n else sprintf("%s[%s]", parts[1], paste(parts[-1], collapse = ","))
  }, character(1))
  df
}

# Mean-field q is Normal on the unconstrained scale. CmdStan's first row is the approximation's
# mean mapped back to the constrained scale, so log() of it is the unconstrained mean; the sd is
# taken from the output draws on the unconstrained scale.
moments_from_csv <- function(path) {
  df <- read_vb_csv(path)
  if (!all(canon$name %in% names(df)))
    stop("Missing Stan columns: ", paste(setdiff(canon$name, names(df)), collapse = ", "),
         "\nAvailable parameters start with: ", paste(head(names(df), 25), collapse = ", "))
  # CmdStan >= 2.33 writes log_p__ / log_g__; older versions wrote lp_approx__
  lp_col <- intersect(c("log_p__", "lp_approx__"), names(df))[1]
  if (is.na(lp_col) || df[[lp_col]][1] != 0 || all(df[[lp_col]][-1] == 0))
    stop("The first row of the variational CSV is not the mean row as assumed.")
  mean_row <- unlist(df[1, canon$name]); draws <- as.matrix(df[-1, canon$name])
  u_mean <- ifelse(canon$is_log, log(mean_row), mean_row)
  for (j in which(canon$is_log)) draws[, j] <- log(draws[, j])
  u_sd <- apply(draws, 2, sd)
  names(u_mean) <- paste0("mean_", seq_along(u_mean)); names(u_sd) <- paste0("sd_", seq_along(u_sd))
  as_tibble_row(c(u_mean, u_sd))
}

done_files <- list.files("best_vi", pattern = "^stan_restarts_moments.*\\.csv$", full.names = TRUE)
done <- unlist(lapply(done_files, function(f) read_csv(f, show_col_types = FALSE)$seed))
message("Stan restarts: seeds ", min(seeds), "..", max(seeds), " -> ", out_file,
        "; already done: ", length(intersect(seeds, done)))
for (s in setdiff(seeds, done)) {
  t0 <- Sys.time()
  fit <- tryCatch(
    do.call(mod$variational, c(list(data = stan_data, seed = s), vi_args)),
    error = function(e) { message("  seed ", s, " failed: ", conditionMessage(e)); NULL })
  if (is.null(fit)) next
  csv <- fit$output_files()[1]
  row <- tryCatch(moments_from_csv(csv), error = function(e) { message("  seed ", s, ": ", conditionMessage(e)); NULL })
  unlink(csv)
  if (is.null(row) || !all(is.finite(unlist(row)))) next
  write_csv(bind_cols(tibble(seed = s), row), out_file, append = file.exists(out_file))
  message(sprintf("  seed %d done in %.0f s", s, as.numeric(difftime(Sys.time(), t0, units = "secs"))))
}
message("Wrote ", out_file, ". Next: python best_vi.py pymc ; python best_vi.py score")
